/**
 * Every failure that crosses the FFI. Variants carry no secrets: details are
 * lengths, states and error kinds only (§2.3 applies to the phone too).
 */
public 
enum E2eeError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A caller-supplied value is malformed (an id, a key length, a size).
     */
    case InvalidArgument(
        /**
         * What was wrong.
         */detail: String
    )
    /**
     * Authentication failed: a bad tag, wrong key or prologue. Never act on
     * the message.
     */
    case Rejected(
        /**
         * Which check.
         */detail: String
    )
    /**
     * A message or blob had the wrong shape.
     */
    case Malformed(
        /**
         * Which check.
         */detail: String
    )
    /**
     * The OS random number generator failed.
     */
    case Random
    /**
     * §4.3: the channel closed with `protocol_error`; its keys are zeroised.
     * Send CLOSE `protocol_error`, discard partial messages, fail pending
     * requests, discard queued input, reconnect and re-seed.
     */
    case ProtocolError(
        /**
         * The violation (counter values only).
         */detail: String
    )
    /**
     * The channel is closed.
     */
    case ChannelClosed(
        /**
         * Why.
         */reason: String
    )
    /**
     * Not allowed in the channel's current state.
     */
    case NotReady
    /**
     * The send counter is exhausted (should have rekeyed long ago).
     */
    case CounterExhausted
    /**
     * A record or payload is too large.
     */
    case TooLarge
    /**
     * A sealed catalog or push came from a key that isn't pinned.
     */
    case WrongSender
    /**
     * Catalog version older than the high-water mark (rollback).
     */
    case CatalogRollback
    /**
     * Same catalog version, different body (equivocation): flag it.
     */
    case CatalogEquivocation
    /**
     * §6.1: the pin store failed its check. Fail closed: pair again.
     */
    case StoreLost(
        /**
         * Which check (no contents).
         */reason: String
    )
    /**
     * File system error (pin store).
     */
    case Io(
        /**
         * The error kind.
         */detail: String
    )
    /**
     * A handshake or session object was used after it was consumed.
     */
    case Consumed
    /**
     * An internal error (a bug).
     */
    case Internal(
        /**
         * What.
         */detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension E2eeError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeE2eeError: FfiConverterRustBuffer {
    typealias SwiftType = E2eeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> E2eeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Rejected(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Malformed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Random
        case 5: return .ProtocolError(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ChannelClosed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NotReady
        case 8: return .CounterExhausted
        case 9: return .TooLarge
        case 10: return .WrongSender
        case 11: return .CatalogRollback
        case 12: return .CatalogEquivocation
        case 13: return .StoreLost(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 14: return .Io(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 15: return .Consumed
        case 16: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: E2eeError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Rejected(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Malformed(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .Random:
            writeInt(&buf, Int32(4))
        
        
        case let .ProtocolError(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ChannelClosed(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotReady:
            writeInt(&buf, Int32(7))
        
        
        case .CounterExhausted:
            writeInt(&buf, Int32(8))
        
        
        case .TooLarge:
            writeInt(&buf, Int32(9))
        
        
        case .WrongSender:
            writeInt(&buf, Int32(10))
        
        
        case .CatalogRollback:
            writeInt(&buf, Int32(11))
        
        
        case .CatalogEquivocation:
            writeInt(&buf, Int32(12))
        
        
        case let .StoreLost(reason):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Io(detail):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .Consumed:
            writeInt(&buf, Int32(15))
        
        
        case let .Internal(detail):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


